// IdentityServiceHandler is an implementation of the sock.v1.IdentityService service.
type IdentityServiceHandler interface {
	SignInWithApple(context.Context, *connect.Request[v1.SignInWithAppleRequest]) (*connect.Response[v1.SignInWithAppleResponse], error)
	RegisterWithApple(context.Context, *connect.Request[v1.RegisterWithAppleRequest]) (*connect.Response[v1.RegisterWithAppleResponse], error)
	// Email through WorkOS AuthKit's hosted page (docs/specs/email-sign-in-pass-2.md).
	SignInWithEmail(context.Context, *connect.Request[v1.SignInWithEmailRequest]) (*connect.Response[v1.SignInWithEmailResponse], error)
	RegisterWithEmail(context.Context, *connect.Request[v1.RegisterWithEmailRequest]) (*connect.Response[v1.RegisterWithEmailResponse], error)
	// A signed-in human adds email sign-in: the session proves the person,
	// AuthKit, an email code or Google the address.
	AddEmailSignIn(context.Context, *connect.Request[v1.AddEmailSignInRequest]) (*connect.Response[v1.AddEmailSignInResponse], error)
	// Email as a six-digit code typed into the app (docs/specs/email-sign-in-pass-3.md).
	StartEmailSignIn(context.Context, *connect.Request[v1.StartEmailSignInRequest]) (*connect.Response[v1.StartEmailSignInResponse], error)
	VerifyEmailSignIn(context.Context, *connect.Request[v1.VerifyEmailSignInRequest]) (*connect.Response[v1.VerifyEmailSignInResponse], error)
	// The address and the WorkOS user's password instead of a code
	// (operator-created humans, the App Review account).
	SignInWithEmailPassword(context.Context, *connect.Request[v1.SignInWithEmailPasswordRequest]) (*connect.Response[v1.SignInWithEmailPasswordResponse], error)
	// Google through WorkOS (docs/specs/google-and-passkey-sign-in.md).
	SignInWithGoogle(context.Context, *connect.Request[v1.SignInWithGoogleRequest]) (*connect.Response[v1.SignInWithGoogleResponse], error)
	// Passkeys for relying party joinsock.com, verified by the hub
	// (docs/specs/google-and-passkey-sign-in.md). Added by a signed-in human;
	// a passkey never creates an account.
	StartPasskeyRegistration(context.Context, *connect.Request[v1.StartPasskeyRegistrationRequest]) (*connect.Response[v1.StartPasskeyRegistrationResponse], error)
	FinishPasskeyRegistration(context.Context, *connect.Request[v1.FinishPasskeyRegistrationRequest]) (*connect.Response[v1.FinishPasskeyRegistrationResponse], error)
	ListPasskeys(context.Context, *connect.Request[v1.ListPasskeysRequest]) (*connect.Response[v1.ListPasskeysResponse], error)
	RemovePasskey(context.Context, *connect.Request[v1.RemovePasskeyRequest]) (*connect.Response[v1.RemovePasskeyResponse], error)
	StartPasskeySignIn(context.Context, *connect.Request[v1.StartPasskeySignInRequest]) (*connect.Response[v1.StartPasskeySignInResponse], error)
	SignInWithPasskey(context.Context, *connect.Request[v1.SignInWithPasskeyRequest]) (*connect.Response[v1.SignInWithPasskeyResponse], error)
	SignOut(context.Context, *connect.Request[v1.SignOutRequest]) (*connect.Response[v1.SignOutResponse], error)
	// Anonymous. Whether registering needs an invite (feature flags spec).
	GetRegistrationPolicy(context.Context, *connect.Request[v1.GetRegistrationPolicyRequest]) (*connect.Response[v1.GetRegistrationPolicyResponse], error)
	GetMe(context.Context, *connect.Request[v1.GetMeRequest]) (*connect.Response[v1.GetMeResponse], error)
	AcceptTerms(context.Context, *connect.Request[v1.AcceptTermsRequest]) (*connect.Response[v1.AcceptTermsResponse], error)
	GetAccounts(context.Context, *connect.Request[v1.GetAccountsRequest]) (*connect.Response[v1.GetAccountsResponse], error)
	LookupHandle(context.Context, *connect.Request[v1.LookupHandleRequest]) (*connect.Response[v1.LookupHandleResponse], error)
	UpdateDisplayName(context.Context, *connect.Request[v1.UpdateDisplayNameRequest]) (*connect.Response[v1.UpdateDisplayNameResponse], error)
	ChangeHandle(context.Context, *connect.Request[v1.ChangeHandleRequest]) (*connect.Response[v1.ChangeHandleResponse], error)
	ListDevices(context.Context, *connect.Request[v1.ListDevicesRequest]) (*connect.Response[v1.ListDevicesResponse], error)
	RevokeDevice(context.Context, *connect.Request[v1.RevokeDeviceRequest]) (*connect.Response[v1.RevokeDeviceResponse], error)
	MintMachineKey(context.Context, *connect.Request[v1.MintMachineKeyRequest]) (*connect.Response[v1.MintMachineKeyResponse], error)
	CreatePuppet(context.Context, *connect.Request[v1.CreatePuppetRequest]) (*connect.Response[v1.CreatePuppetResponse], error)
	ListPuppets(context.Context, *connect.Request[v1.ListPuppetsRequest]) (*connect.Response[v1.ListPuppetsResponse], error)
	MintPuppetToken(context.Context, *connect.Request[v1.MintPuppetTokenRequest]) (*connect.Response[v1.MintPuppetTokenResponse], error)
	ErasePuppet(context.Context, *connect.Request[v1.ErasePuppetRequest]) (*connect.Response[v1.ErasePuppetResponse], error)
	// A puppet whose agent session ended, and its resumption.
	ArchivePuppet(context.Context, *connect.Request[v1.ArchivePuppetRequest]) (*connect.Response[v1.ArchivePuppetResponse], error)
	UnarchivePuppet(context.Context, *connect.Request[v1.UnarchivePuppetRequest]) (*connect.Response[v1.UnarchivePuppetResponse], error)
	// Connector service only (sock_ct_ bearer).
	IssueConnectorPuppetToken(context.Context, *connect.Request[v1.IssueConnectorPuppetTokenRequest]) (*connect.Response[v1.IssueConnectorPuppetTokenResponse], error)
	RevokeConnectorDevice(context.Context, *connect.Request[v1.RevokeConnectorDeviceRequest]) (*connect.Response[v1.RevokeConnectorDeviceResponse], error)
	ExportIdentityData(context.Context, *connect.Request[v1.ExportIdentityDataRequest]) (*connect.Response[v1.ExportIdentityDataResponse], error)
	EraseAccount(context.Context, *connect.Request[v1.EraseAccountRequest]) (*connect.Response[v1.EraseAccountResponse], error)
	// Sock Pro on the web, through Stripe (docs/specs/sock-pro-billing.md).
	// Both open a page in the browser; the app re-reads GetMe on return.
	StartCheckout(context.Context, *connect.Request[v1.StartCheckoutRequest]) (*connect.Response[v1.StartCheckoutResponse], error)
	OpenBillingPortal(context.Context, *connect.Request[v1.OpenBillingPortalRequest]) (*connect.Response[v1.OpenBillingPortalResponse], error)
}

